+        LoadAlign<bfloat16_t, LoadDist::DIST_UNPACK_B16>(xBFp16MainB2, mainAddr2 + offset2);
+        LoadAlign<bfloat16_t, LoadDist::DIST_UNPACK_B16>(xBFp16TailA2, tailAddr2 + offset1);
