+            LocalTensor<T> xOutLocal = outQueueX.AllocTensor<T>();
+            uint32_t calCount = CeilAlign((uint64_t)(calColNum * sizeof(T)), ALIGN_512_FACTOR) / sizeof(T);
+            if constexpr (!is_same<T, float>::value) {
+                if (nullptrBeta) {
