+template <typename T>
+__aicore__ inline void CastStoreTwoCloseRegVF(__local_mem__ T* dstAddr, RegTensor<float>& srcA, RegTensor<float>& srcB,
+                                              uint16_t offset, MaskReg& pregLoop)
+{
+    if constexpr (IsSameType<T, float>::value) {
