+        static_cast<uint32_t>(blockLen * sizeof(T)), // blockLen
+        srcStride,                                   // srcStride
+        dstStride,                                   // dstStride
+        0                                            // rsv
+    };
+    if constexpr (is_same<U, AscendC::LocalTensor<T>>::value) {
+        DataCopyPad(dstTensor, srcTensor, extParams, padParams);
